import React from 'react';
import { useNavigate } from 'react-router-dom';
import SearchBar from '../components/SearchBar';
import './Home.css'; // Assuming you have a CSS file for styles

export default function Home() {
  const navigate = useNavigate();

  const handleSearch = ({ name, continent }) => {
    const params = new URLSearchParams();
    if (name) params.set('name', name);
    if (continent) params.set('continent', continent);
    params.set('page', 1);
    navigate(`/search?${params.toString()}`);
  };

  return (
    <div className="home">
        <div className="overlay-content">
            <img className="full-page-background" src="/images/earth.png" alt="Earth" />
            <h1>Welcome to the Country Search App</h1>
            <p>Find information about countries around the world.</p>
            <SearchBar onSearch={handleSearch} compact={true} />
      </div>
    </div>
  );
}
